import { readFileSync, writeFileSync } from 'node:fs'
import { searchShortcutsMarkdown } from '../src/lib/searchShortcutDefinitions'

const path = new URL('../docs/search-shortcuts.md', import.meta.url)
const markdown =
    '<!-- Generated by npm run docs:shortcuts. Edit src/integrations/poe-trade/filterDefinitions.ts or src/lib/searchShortcutDefinitions.ts. -->\n\n' +
    searchShortcutsMarkdown()
if (process.argv.includes('--check')) {
    if (readFileSync(path, 'utf8') !== markdown)
        throw new Error('Shortcut docs are out of date. Run npm run docs:shortcuts.')
} else {
    writeFileSync(path, markdown)
}
